questionvariables.text:
/* Randomly select angle A */
A: 35+5*rand(4);

/* Randomly select side a */
side_a: 8+rand(5);

/* Randomly select side b such that b < a */
side_b: 5+rand(side_a-6);

/* Convert angle A to radians */
A_rad: A*%pi/180;

/* Calculate sin(B) using the Sine Rule */
sin_B: side_b*sin(A_rad)/side_a;

/* Calculate angle B in radians */
B_rad: asin(sin_B);

/* Convert angle B to degrees */
B_deg: B_rad*180/%pi;

/* Round the teacher answer to 1 decimal place */
ta1: round(B_deg*10)/10;

/* Calculate side c using the Cosine Rule */
side_c: float(
    side_b*cos(A_rad)
    +sqrt(side_a^2-side_b^2*sin(A_rad)^2)
);
